-- Import of the mc changelog ("Für Spieler" part of CHANGELOG_MD, src/generated/changelog.js, mc-stack@76b1844) into the changelog table,
-- so the history is in D1 next to the automatic rows. area 'server', status live, version 1, edited 0, one row per entry,
-- source 'import:mc-<YYYY-MM-DD>-<n>' (n = position within the day). Undated entries are skipped. Idempotent: the unique
-- index on changelog.source (0022) makes INSERT OR IGNORE add nothing on a re-run. Applied by CF Deployer after 0022:
--   npx wrangler d1 execute nwebnotfound-guestbook --remote --file migrations/0023_changelog_import.sql

INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-06', 'server', 'Neue Startseite', 'New home page', 'Die Hauptseite stellt Nils und seine Projekte vor, mit Steckbrief, Projektkarten und den letzten Neuigkeiten.', 'The main page introduces Nils and his projects, with a profile card, project cards and the latest news.', 'live', 1, 1, 1762560000000, 'import:mc-2026-11-06-1', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-06', 'server', 'VIP-Welten über die Website', 'VIP worlds from the website', 'Auf der Website legst du deine VIP-Welten an, startest, benennst und stellst sie ein und lädst Freunde ein; Erfolg meldet die Seite erst, wenn der Server die Aktion bestätigt hat.', 'On the website you create, start, rename and configure your VIP worlds and invite friends; the page only reports success once the server has confirmed the action.', 'live', 2, 1, 1762560000000, 'import:mc-2026-11-06-2', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-06', 'server', 'Schnellere Website', 'Faster website', 'Styles, Skripte und Bilder werden besser zwischengespeichert; Bilder außerhalb des sichtbaren Bereichs laden erst bei Bedarf.', 'Styles, scripts and images are cached better; images outside the visible area load only when needed.', 'live', 3, 1, 1762560000000, 'import:mc-2026-11-06-3', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-06', 'server', 'Eine Navigation für alles', 'One navigation for everything', 'Hauptseite und Server-Seite teilen sich jetzt dieselbe Navigationsleiste, auch auf dem Handy.', 'The main site and the server site now share the same navigation bar, on phones too.', 'live', 4, 1, 1762560000000, 'import:mc-2026-11-06-4', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-05', 'server', 'Backup ohne Unterbrechung', 'Backup without downtime', 'Das tägliche Backup um 00:00 läuft jetzt im laufenden Betrieb: Der Server wird nicht mehr gestoppt und du fliegst nicht raus.', 'The daily backup at 00:00 now runs while the server is up: it is no longer stopped and you are not kicked.', 'live', 1, 1, 1762560000000, 'import:mc-2026-11-05-1', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-05', 'server', 'Portale und VIP-Welten wieder zuverlässig', 'Portals and VIP worlds work again', 'Das Wechseln zwischen den Servern über Portale und NPCs funktioniert wieder, und Starten und Betreten von VIP-Welten wurde repariert; wenn etwas nicht klappt, bekommst du eine Meldung im Chat.', 'Switching between servers through portals and NPCs works again, starting and entering VIP worlds was repaired, and you get a chat message if something does not work.', 'live', 2, 1, 1762560000000, 'import:mc-2026-11-05-2', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-01', 'server', 'Echte Spielerköpfe auf der Website', 'Real player heads on the website', 'Auf der Website siehst du jetzt überall echte Spielerköpfe: in der Spielerliste, im Profil und oben in deiner Konto-Anzeige.', 'On the website you now see real player heads everywhere: in the player list, in the profile and in your account display at the top.', 'live', 1, 1, 1762560000000, 'import:mc-2026-11-01-1', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-01', 'server', 'Kills heißen „Spieler-Kills“', 'Kills are called “Player kills”', 'Im Profil heißen Kills jetzt „Spieler-Kills“, gezählt werden nur Kills an anderen Spielern.', 'In the profile, kills are now called “Player kills”; only kills on other players are counted.', 'live', 2, 1, 1762560000000, 'import:mc-2026-11-01-2', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-01', 'server', 'Rüstung und Offhand im Inventar', 'Armour and offhand in the inventory', 'Im Inventar auf der Website haben Rüstung und Offhand jetzt eigene, richtige Slots.', 'In the website inventory, armour and offhand now have their own proper slots.', 'live', 3, 1, 1762560000000, 'import:mc-2026-11-01-3', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-01', 'server', 'Deutsche Itemnamen in Bestellungen', 'German item names in orders', 'Deine Bestellungen zeigen jetzt deutsche Itemnamen, zum Beispiel „Fass“ statt „barrel“.', 'Your orders now show German item names, for example “Fass” instead of “barrel”.', 'live', 4, 1, 1762560000000, 'import:mc-2026-11-01-4', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-11-01', 'server', 'Tode in zwei Listen', 'Deaths in two lists', 'Deine Tode stehen jetzt in zwei Listen: „Getötet von“ für Mobs und „Todesursachen“ für alles andere.', 'Your deaths now appear in two lists: “Killed by” for mobs and “Causes of death” for everything else.', 'live', 5, 1, 1762560000000, 'import:mc-2026-11-01-5', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-10-31', 'server', 'PvP-Bestenliste im Discord', 'PvP leaderboard on Discord', 'Neu im Discord: /leaderboard pvp zeigt die PvP-Bestenliste mit Siegen, Niederlagen, Unentschieden, Winrate (ab 5 Matches) und Lieblings-Kit.', 'New on Discord: /leaderboard pvp shows the PvP leaderboard with wins, losses, draws, win rate (from 5 matches) and favourite kit.', 'live', 1, 1, 1762560000000, 'import:mc-2026-10-31-1', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-10-31', 'server', 'NPCs in der Lobby', 'NPCs in the lobby', 'In der Lobby stehen jetzt NPCs. Schau sie aus der Nähe an, dann siehst du, was sie machen; per Klick bringen sie dich zum Beispiel auf einen anderen Server oder öffnen ein Menü.', 'There are NPCs in the lobby now. Look at one up close to see what it does; clicking one takes you to another server or opens a menu, for example.', 'live', 2, 1, 1762560000000, 'import:mc-2026-10-31-2', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-10-31', 'server', 'Neue Ränge', 'New ranks', 'Es gibt jetzt Ränge: Spieler, VIP, MVP, Builder und Admin. In der Lobby siehst du den Rang farbig im Chat, in der Tabliste und über dem Kopf.', 'There are ranks now: Player, VIP, MVP, Builder and Admin. In the lobby you see your rank in colour in chat, in the tab list and above your head.', 'live', 3, 1, 1762560000000, 'import:mc-2026-10-31-3', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-10-31', 'server', 'Teamfarben in Survival', 'Team colours in Survival', 'In Survival zeigt dein Name die Farbe deines Teams. Team-Owner stellen sie mit /team color <farbe> ein (z. B. blau, gelb, lila).', 'In Survival your name shows your team''s colour. Team owners set it with /team color <colour> (e.g. blue, yellow, purple).', 'live', 4, 1, 1762560000000, 'import:mc-2026-10-31-4', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-10-31', 'server', 'AFK-Markierung hinter dem Namen', 'AFK marker behind the name', 'Die AFK-Markierung steht jetzt hinter deinem Namen und überschreibt den Rang nicht mehr.', 'The AFK marker now sits behind your name and no longer overrides the rank.', 'live', 5, 1, 1762560000000, 'import:mc-2026-10-31-5', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-10-31', 'server', 'Verkaufen Stack für Stack', 'Selling stack by stack', 'Du verkaufst jetzt Stack für Stack statt alles auf einmal.', 'You now sell stack by stack instead of everything at once.', 'live', 6, 1, 1762560000000, 'import:mc-2026-10-31-6', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-10-31', 'server', 'Items zurück nach Offline-Verkauf', 'Items back after an offline sale', 'Wenn du während eines Verkaufs offline gehst, bekommst du deine Items beim nächsten Einloggen zurück.', 'If you go offline during a sale, you get your items back the next time you log in.', 'live', 7, 1, 1762560000000, 'import:mc-2026-10-31-7', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-10-31', 'server', 'Preisvorschau im Verkaufsmenü', 'Price preview in the sell menu', 'Im Verkaufsmenü siehst du vorher, wie viel du für deine Items bekommst.', 'In the sell menu you now see beforehand how much you get for your items.', 'live', 8, 1, 1762560000000, 'import:mc-2026-10-31-8', 0);
INSERT OR IGNORE INTO changelog (day, area, title_de, title_en, text_de, text_en, status, sort, version, updated_at, source, edited) VALUES ('2026-10-31', 'server', 'Verkaufen vorerst aus', 'Selling is off for now', 'Verkaufen ist vorerst ausgeschaltet. Wir sagen Bescheid, sobald es wieder geht.', 'Selling is switched off for now. We''ll let you know as soon as it works again.', 'live', 9, 1, 1762560000000, 'import:mc-2026-10-31-9', 0);
